import test from "node:test";
import assert from "node:assert/strict";
import { K8sController, translateAgentSpecToRunPayload } from "../src/index.js";
import { sampleBundle } from "./fixtures.js";

test("k8s-crd translates agent spec to run payload", () => {
  const bundle = sampleBundle();
  const runPayload = translateAgentSpecToRunPayload(
    bundle.agentSpec,
    { "anthropic-main": bundle.modelConfigs[0] },
    { "tools-main": bundle.toolServers[0] }
  );

  assert.equal(runPayload.function_id, "run::start");
  assert.equal(runPayload.payload.session_id, "session-1");
  assert.equal(runPayload.payload.provider, "anthropic");
  assert.equal(runPayload.payload.k8s_context.tool_servers[0], "tools-main");
});

test("k8s-controller emits idempotent actions", () => {
  const controller = new K8sController();
  const bundle = sampleBundle();
  const triggered = [];
  const triggerFn = (functionId, payload) => triggered.push({ functionId, payload });

  const first = controller.reconcileNow(bundle, triggerFn);
  assert.equal(first.healthy, true);
  assert.ok(triggered.length >= 2);

  const secondDiff = controller.diff(bundle);
  assert.ok(secondDiff.actions.every((a) => a.type === "noop"));
});

