import { payloadHash } from "./hash.js";

function actionId(type, target) {
  return `${type}:${target}`;
}

function upsertOrNoop(type, target, payload, observedByTarget) {
  const hash = payloadHash(payload);
  const observedHash = observedByTarget.get(target);
  if (observedHash === hash) {
    return {
      id: actionId("noop", target),
      type: "noop",
      target,
      payloadHash: hash,
      payload: { reason: "unchanged" }
    };
  }

  return {
    id: actionId(type, target),
    type,
    target,
    payloadHash: hash,
    payload
  };
}

export function buildDesiredGraph({ runPayload, providerPayload, toolPayloads }) {
  return {
    provider: providerPayload,
    run: runPayload,
    tools: toolPayloads
  };
}

export function reconcileDesiredVsObserved(desiredGraph, observedByTarget = new Map()) {
  const actions = [];

  actions.push(
    upsertOrNoop(
      "upsert-provider-config",
      "provider/default",
      desiredGraph.provider,
      observedByTarget
    )
  );

  actions.push(
    upsertOrNoop(
      "start-or-update-run",
      `run/${desiredGraph.run.payload.session_id}`,
      desiredGraph.run,
      observedByTarget
    )
  );

  for (const toolPayload of desiredGraph.tools) {
    actions.push(
      upsertOrNoop(
        "upsert-toolserver-bridge",
        `tool/${toolPayload.payload.name}`,
        toolPayload,
        observedByTarget
      )
    );
  }

  return actions;
}
